 * doesn't carry directly — every issue notification links here. */
async function issueHref(orgId: OrgId, issueId: IssueId): Promise<string | null> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!issue) return null;

  const [org, project] = await Promise.all([
    orgRepo.findOrgById(orgId),
    projectRepo.findProjectById(orgId, issue.projectId),
  ]);
  if (!org || !project) return null;

  return issuePath(org.slug, project.slug, issue.number);
}

async function ownerUserIds(orgId: OrgId): Promise<readonly UserId[]> {
  const owners = await memberRepo.listMembers({
    orgId,
    role: "owner",
    status: undefined,
    query: undefined,
    limit: 50,
    cursor: null,
  });
  return owners.items.map((member) => member.userId);
}

/**
 * The bus wiring. Attached at module load rather than from `event-registry`
 * because the fan-out has no other public entry point — importing this module
 * is what makes an org start receiving notifications.
 */
let registered = false;

function registerFanOut(): void {
  if (registered) return;
  registered = true;

  subscribe("issue.assigned", async (payload) => {
    const href = await issueHref(payload.orgId, payload.issueId);
    if (href === null) return;
    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.issueId} is now yours`,
      href,
      actorId: payload.actorId,
    });
  });

  // An assignee set at creation time is told exactly as if assigned later;
  // `issue.created` always fires, so this is the only place that case needs
  // handling. `notify()` already drops the actor from the recipient set, so
  // creating an issue and assigning yourself produces nothing.
  subscribe("issue.created", async (payload) => {
    if (payload.assigneeId === null) return;
    const href = await issueHref(payload.orgId, payload.issueId);
    if (href === null) return;
    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.issueId} is now yours`,
      href,
      actorId: payload.actorId,
    });
  });

  // Only the assignee cares that someone moved their issue; an issue with no
  // assignee, or a change the assignee made themselves, notifies nobody.
  subscribe("issue.status_changed", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue || issue.assigneeId === null) return;

    const href = await issueHref(payload.orgId, payload.issueId);
    if (href === null) return;

    await notify(payload.orgId, "issue_status_changed", [issue.assigneeId], {
      title: "An issue you own changed status",
      body: `Issue ${payload.issueId} moved from ${payload.from} to ${payload.to}`,
      href,
      actorId: payload.actorId,
    });
  });

  subscribe("issue.overdue", async (payload) => {
    if (payload.assigneeId === null) return;
    const href = await issueHref(payload.orgId, payload.issueId);
    if (href === null) return;
    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
      title: "An issue is overdue",
      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
      href,
      actorId: null,
    });
  });

  subscribe("comment.created", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    const watchers = issue
      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]
      : [];
    const href = await issueHref(payload.orgId, payload.issueId);
    if (href === null) return;

    await notify(payload.orgId, "comment_created", watchers, {
      title: "New comment",
      body: `A comment was added to issue ${payload.issueId}`,
      href,
      actorId: payload.actorId,
    });

    if (payload.mentionedUserIds.length > 0) {
      await notify(
        payload.orgId,
        "comment_mention",
        payload.mentionedUserIds,
        {
          title: "You were mentioned",
          body: `You were mentioned on issue ${payload.issueId}`,
          href,
          actorId: payload.actorId,
        },
      );
    }
  });

  // The owner is told a new member joined; the person who joined already
  // knows — they just joined.
  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    const owners = await ownerUserIds(payload.orgId);
    await notify(payload.orgId, "member_joined", owners, {
      title: "A new member joined",
      body: `${payload.userId} joined ${org.name} as ${payload.role}`,
      href: settingsPath(org.slug, "members"),
      actorId: payload.userId,
    });
  });

  // A refused write never leaves the owner uninformed, but a still-unread
  // alert for the same resource absorbs further refusals — only once it's
  // read does the next refusal produce a fresh one.
  subscribe("billing.limit_exceeded", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    const href = withSearchParams(settingsPath(org.slug, "billing"), {
      resource: payload.resource,
    });
    const owners = await ownerUserIds(payload.orgId);

    for (const ownerId of owners) {
      if (ownerId === payload.actorId) continue;

      const existing = await notificationRepo.listNotifications({
        orgId: payload.orgId,
        recipientId: ownerId,
        unreadOnly: true,
        kind: ["plan_limit_reached"],
        limit: 25,
        cursor: null,
      });
      if (existing.items.some((item) => item.href === href)) continue;

      await notify(payload.orgId, "plan_limit_reached", [ownerId], {
        title: "Plan limit reached",
        body: `${payload.resource} is at ${payload.used}/${payload.limit} on the current plan`,
        href,
        actorId: payload.actorId,
      });
    }
  });
}

registerFanOut();

