/**
 * A hit's `subjectId` is only ever a raw entity id, never a slug or number,
 * so every link needs a lookup — an issue hit resolves to its issue page, a
 * comment hit resolves to the issue it was posted on, and a project hit
 * resolves to the project page. `null` means the entity no longer exists
 * (the index lags deletes), and such a hit is dropped rather than linked
 * to a dead page.
 */
async function hrefFor(
  orgId: OrgId,
  kind: SearchSubjectKind,
  subjectId: string,
): Promise<string | null> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return null;

  switch (kind) {
    case "issue": {
      const issue = await issueRepo.findIssueById(orgId, subjectId as Issue["id"]);
      if (!issue) return null;
      const project = await projectRepo.findProjectById(orgId, issue.projectId);
      if (!project) return null;
      return issuePath(org.slug, project.slug, issue.number);
    }
    case "comment": {
      const comment = await commentRepo.findCommentById(
        orgId,
        subjectId as Comment["id"],
      );
      if (!comment) return null;
      const issue = await issueRepo.findIssueById(orgId, comment.issueId);
      if (!issue) return null;
      const project = await projectRepo.findProjectById(orgId, issue.projectId);
      if (!project) return null;
      return issuePath(org.slug, project.slug, issue.number);
    }
    case "project": {
      const project: Project | null = await projectRepo.findProjectById(
        orgId,
        subjectId as Project["id"],
      );
      if (!project) return null;
      return projectPath(org.slug, project.slug);
    }
  }
}

